      c.fillStyle = hsl(28, 6 + rnd() * 10, 24 + rnd() * 16, 0.28);
      c.beginPath(); c.ellipse(rnd() * w, rnd() * h, 4 + rnd() * 10, 10 + rnd() * 26, 0, 0, TAU); c.fill();
