      const a2 = j / sides * TAU, cs = Math.cos(a2), sn = Math.sin(a2);
      const nx = u[0] * cs + v[0] * sn, ny = u[1] * cs + v[1] * sn, nz = u[2] * cs + v[2] * sn;
      const r = radii[k];
      const [tu, tw] = tuv(tile, j / sides, tri);
      ring.push(gb.vert(pts[k][0] + nx * r, pts[k][1] + ny * r, pts[k][2] + nz * r, nx, ny, nz, tu, tw, col, sway ? sway[k] : 0));
