      const cd = vnorm([d2[0] * ct + (u2[0] * ca + v2[0] * sa) * st, d2[1] * ct + (u2[1] * ca + v2[1] * sa) * st + 0.2, d2[2] * ct + (u2[2] * ca + v2[2] * sa) * st]);
