    const az = k / n * TAU + rnd() * 0.8, el = 0.45 + rnd() * 0.85;
    const ax = [Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el)];
    const side = vnorm(vcross(ax, [rnd() - 0.5, rnd() * 0.6, rnd() - 0.5]));
