  const wob = ys.map((y, i) => [i < 2 ? 0 : (rnd() - 0.5) * 0.14, y, i < 2 ? 0 : (rnd() - 0.5) * 0.14]);
  const rad = [0.31, 0.25, 0.22, 0.2, 0.17];
