    const [t1, t2] = perpFrame(d);
    const p0 = P(d[0], d[1], d[2]);
    const p1 = P(d[0] + t1[0] * e, d[1] + t1[1] * e, d[2] + t1[2] * e);
    const p2 = P(d[0] + t2[0] * e, d[1] + t2[1] * e, d[2] + t2[2] * e);
    let nn = vnorm(vcross([p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]], [p2[0] - p0[0], p2[1] - p0[1], p2[2] - p0[2]]));
    if (nn[0] * p0[0] + nn[1] * p0[1] + nn[2] * p0[2] < 0) nn = [-nn[0], -nn[1], -nn[2]];
    pos.set(p0, i * 3); nrm.set(nn, i * 3);
